package com.example.shelflife;
import android.content.Context;
import android.database.sqlite.SQLiteDatabase;
import androidx.room.Room;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;
import org.junit.runner.RunWith;
import java.time.LocalDate;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class GroceryIntegrationTest {
 AppDatabase db;StockRepository repo;long user;
 @Before public void setup(){Context c=ApplicationProvider.getApplicationContext();db=Room.inMemoryDatabaseBuilder(c,AppDatabase.class).allowMainThreadQueries().build();Staff s=new Staff();s.name="Test staff";s.email="staff@example.com";s.salt=Passwords.salt();s.passwordHash=Passwords.hash("ExamplePass123!",s.salt);user=db.productDao().insert(s);repo=new StockRepository(db,user);}
 @After public void close(){db.close();}
 Product receive(String sku,int days,double quantity,boolean existing){Product p=new Product("Milk",sku,"LOT","Dairy and Eggs",quantity,LocalDate.now().plusDays(days).toEpochDay());p.stockReference="B"+(db.productDao().sku(sku).size()+1);p.barcode="0012345678905";repo.receive(p,existing,true);return p;}
 @Test public void sameProductDifferentDatesStaySeparate(){Product a=receive("MILK",1,24,false),b=receive("MILK",7,12,true);assertNotEquals(a.id,b.id);assertEquals(2,db.productDao().sku("MILK").size());assertEquals(24,db.productDao().get(a.id).quantity,0);assertEquals(a.id,db.productDao().barcode("0012345678905").id);assertNull(db.productDao().barcode("12345678905"));}
 @Test public void duplicateBarcodeAcrossProductsRejected(){receive("MILK",1,24,false);try{receive("OTHER",7,12,false);fail();}catch(IllegalArgumentException expected){}assertEquals(1,db.productDao().getAll().size());}
 @Test public void overdrawAndExpiredSaleLeaveLedgerUnchanged(){Product p=receive("MILK",-1,4,false);try{repo.out(p.id,1,"Sold","");fail();}catch(IllegalArgumentException expected){}try{repo.out(p.id,5,"Expired","");fail();}catch(IllegalArgumentException expected){}assertEquals(4,db.productDao().get(p.id).quantity,0);assertEquals(1,db.productDao().movements().size());}
 @Test public void insertFailureRollsBackQuantity(){Product p=receive("MILK",1,4,false);db.getOpenHelper().getWritableDatabase().execSQL("CREATE TRIGGER fail_move BEFORE INSERT ON grocery_movements BEGIN SELECT RAISE(ABORT,'test failure'); END");try{repo.out(p.id,1,"Sold","");fail();}catch(RuntimeException expected){}assertEquals(4,db.productDao().get(p.id).quantity,0);assertEquals(1,db.productDao().movements().size());}
 @Test public void reversalIsAppendOnlyAndOneTime(){Product p=receive("MILK",1,4,false);repo.out(p.id,2,"Damaged","");long move=db.productDao().movements().get(0).id;repo.reverse(move,"Count correction");assertEquals(4,db.productDao().get(p.id).quantity,0);assertEquals(3,db.productDao().movements().size());try{repo.reverse(move,"Again");fail();}catch(IllegalArgumentException expected){}}
 @Test public void fefoSkipsExpiredAndDepleted(){receive("MILK",-1,4,false);Product later=receive("MILK",7,4,true),early=receive("MILK",1,4,true);assertEquals(early.id,StockRepository.fefo(db.productDao().getAll(),"MILK").id);repo.out(early.id,4,"Sold","");assertEquals(later.id,StockRepository.fefo(db.productDao().getAll(),"MILK").id);}
 @Test public void archivingKeepsLedger(){Product p=receive("MILK",1,4,false);repo.archive("MILK",true);assertTrue(db.productDao().get(p.id).archived);assertEquals(4,db.productDao().get(p.id).quantity,0);repo.delete("MILK");assertTrue(db.productDao().get(p.id).deleted);repo.archive("MILK",false);Product restored=db.productDao().get(p.id);assertFalse(restored.archived);assertFalse(restored.deleted);assertEquals(4,restored.quantity,0);assertEquals(1,db.productDao().movements().size());}
 @Test public void lifecycleWriteFailureRollsBack(){Product first=receive("MILK",1,4,false);Product second=receive("MILK",2,2,true);db.getOpenHelper().getWritableDatabase().execSQL("CREATE TRIGGER fail_status BEFORE UPDATE ON products WHEN NEW.id="+second.id+" BEGIN SELECT RAISE(ABORT,'test failure'); END");try{repo.delete("MILK");fail();}catch(RuntimeException expected){}assertFalse(db.productDao().get(first.id).archived);assertFalse(db.productDao().get(first.id).deleted);}

 @Test public void registrationRequiresApprovalAndRejectsDuplicates(){try{Auth.register(db,"Other","other@example.com","ExamplePass123!","","bad");fail();}catch(IllegalArgumentException expected){}Staff s=Auth.register(db,"Other","other@example.com","ExamplePass123!","staff@example.com","ExamplePass123!");assertEquals(s.id,Auth.login(db.productDao(),"OTHER@example.com","ExamplePass123!").id);try{Auth.register(db,"Other","OTHER@example.com","ExamplePass123!","staff@example.com","ExamplePass123!");fail();}catch(IllegalArgumentException expected){}}
 @Test public void reminderIdentityIsUnique(){Product p=receive("MILK",3,4,false);Reminder r=new Reminder();r.batchId=p.id;r.createdDay=LocalDate.now().toEpochDay();r.milestone=3;assertTrue(db.productDao().insert(r)>0);assertEquals(-1,db.productDao().insert(r));assertEquals(1,db.productDao().reminderCount(p.id));}
 @Test public void unknownDateNeverInvented(){Product p=new Product("Pechay","PECHAY","LOT","Fruits and Vegetables",2.5,null);p.stockReference="B1";p.unit="kg";repo.receive(p,false,false);assertNull(db.productDao().get(p.id).expiryDate);assertTrue(Expiry.label(db.productDao().get(p.id)).contains("unknown"));}
 @Test public void actualV1Migration(){Context c=ApplicationProvider.getApplicationContext();String name="grocery-migration-test.db";c.deleteDatabase(name);SQLiteDatabase old=c.openOrCreateDatabase(name,0,null);old.execSQL("CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,name TEXT,sku TEXT,batchNo TEXT,category TEXT,quantity INTEGER NOT NULL,expiryDate INTEGER NOT NULL)");for(String col:new String[]{"sku","name","batchNo"})old.execSQL("CREATE INDEX index_products_"+col+" ON products("+col+")");old.execSQL("INSERT INTO products VALUES(1,'Milk','MILK','LOT','Dairy',24,22000)");old.setVersion(1);old.close();AppDatabase migrated=Room.databaseBuilder(c,AppDatabase.class,name).addMigrations(AppDatabase.MIGRATION_1_3,AppDatabase.MIGRATION_3_4,AppDatabase.MIGRATION_4_5,AppDatabase.MIGRATION_5_6,AppDatabase.MIGRATION_6_7,AppDatabase.MIGRATION_7_8,AppDatabase.MIGRATION_8_9,AppDatabase.MIGRATION_9_10,AppDatabase.MIGRATION_10_11).allowMainThreadQueries().build();try{assertEquals(24,migrated.productDao().get(1).quantity,0);assertEquals("Dairy and Eggs",migrated.productDao().get(1).category);assertEquals(0,migrated.productDao().staffCount());}finally{migrated.close();c.deleteDatabase(name);}}
 @Test public void explicitAndCustomCategories(){Product p=new Product("Pechay","PECHAY","LOT","",2.5,null);try{repo.receive(p,false,false);fail();}catch(IllegalArgumentException expected){}p.stockReference="B1";p.category="Local Produce";repo.receive(p,false,false);assertEquals("Local Produce",db.productDao().get(p.id).category);Product change=p.copy();change.category="Fruits and Vegetables";repo.edit(change);assertEquals("Fruits and Vegetables",db.productDao().get(p.id).category);}
 @Test public void receivingCanReclassifyAllProductStock(){Product first=receive("MILK",1,24,false);Product next=first.copy();next.id=0;next.stockReference="B2";next.quantity=12;next.category="Chilled Dairy";repo.receive(next,true,false);for(Product row:db.productDao().sku("MILK"))assertEquals("Chilled Dairy",row.category);}
 @Test public void failedIntakeDoesNotPartiallyChangeCategory(){Product first=receive("MILK",1,24,false);Product next=first.copy();next.id=0;next.stockReference="B2";next.quantity=-1;next.category="Wrong category";try{repo.receive(next,true,false);fail();}catch(IllegalArgumentException expected){}assertEquals("Dairy and Eggs",db.productDao().get(first.id).category);}
 @Test public void v3ProfileMigrationPreservesAccount(){androidx.sqlite.db.SupportSQLiteDatabase sql=db.getOpenHelper().getWritableDatabase();sql.execSQL("DROP TABLE grocery_staff");sql.execSQL("CREATE TABLE grocery_staff (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,name TEXT,email TEXT,salt TEXT,passwordHash TEXT)");sql.execSQL("INSERT INTO grocery_staff VALUES(1,'Existing staff','old@example.com','salt','hash')");AppDatabase.MIGRATION_3_4.migrate(sql);try(android.database.Cursor cursor=sql.query("SELECT name,email,phone,photoPath FROM grocery_staff WHERE id=1")){assertTrue(cursor.moveToFirst());assertEquals("Existing staff",cursor.getString(0));assertEquals("old@example.com",cursor.getString(1));assertTrue(cursor.isNull(2));assertTrue(cursor.isNull(3));}}
 @Test public void optionalPhotoSharedAndRetainedOnRestore(){Product first=receive("MILK",1,4,false);assertNull(db.productDao().get(first.id).photoPath);Product change=first.copy();change.photoPath="private-photo-example";repo.edit(change);Product next=receive("MILK",3,2,true);assertEquals("private-photo-example",db.productDao().get(next.id).photoPath);repo.delete("MILK");repo.archive("MILK",false);assertEquals("private-photo-example",db.productDao().get(first.id).photoPath);change.photoPath=null;repo.edit(change);assertNull(db.productDao().get(next.id).photoPath);}
 @Test public void passwordChangeRequiresCurrentAndPreservesAccount(){try{PasswordDialog.change(db,user,"wrong","NewPassword123!","NewPassword123!");fail();}catch(IllegalArgumentException expected){}assertNotNull(Auth.login(db.productDao(),"staff@example.com","ExamplePass123!"));PasswordDialog.change(db,user,"ExamplePass123!","NewPassword123!","NewPassword123!");assertEquals(user,Auth.login(db.productDao(),"staff@example.com","NewPassword123!").id);try{Auth.login(db.productDao(),"staff@example.com","ExamplePass123!");fail();}catch(IllegalArgumentException expected){}}
 @Test public void catalogMissingAndPartialResponses()throws Exception{assertTrue(BarcodeLookup.parse("{\"status\":0}").message.contains("No catalog"));BarcodeLookup.Result r=BarcodeLookup.parse("{\"status\":1,\"product\":{\"product_name\":\"Milk\",\"brands\":\"Example\",\"quantity\":\"1 L\"}}");assertEquals("Milk",r.name);assertEquals("Example",r.brand);assertEquals("1 L",r.pack);assertEquals("",r.category);}
 @Test public void descriptionAndPackPersistAcrossStock(){Product first=receive("MILK",1,4,false);Product change=first.copy();change.description="Whole milk";change.packSize="1 L";repo.edit(change);Product next=receive("MILK",3,2,true);assertEquals("Whole milk",db.productDao().get(next.id).description);assertEquals("1 L",db.productDao().get(next.id).packSize);}
 @Test public void generatedSkuAndSingleParent(){Product a=new Product("Mega sardines","","LOT","Canned Goods",3,null);a.stockReference="B1";a.barcode="12345678";a.measurementValue="155";a.measurementUnit="g";a.brand="Mega";a.packSize="155g";a.variation="Tomato sauce";repo.register(a,false);assertEquals("SAR-MEG-155-TS",a.sku);Product b=a.copy();b.id=0;b.stockReference="B2";b.quantity=2;repo.receive(b,true,false);assertEquals(a.productId,b.productId);assertNotEquals(a.id,b.id);Product collision=a.copy();collision.id=0;collision.barcode="23456789";collision.name="Mega sardines premium";repo.register(collision,false);assertEquals(a.sku+"-2",collision.sku);}
 @Test public void editBatchAndIdentityInPlace(){Product first=receive("MILK",1,4,false);Product second=receive("MILK",3,2,true);Product changed=first.copy();changed.unit="bottles";changed.quantity=7;changed.received=7;changed.location="Shelf B";changed.variation="Whole";changed.expiryDate=java.time.LocalDate.now().plusDays(9).toEpochDay();repo.editFull(changed,true);assertEquals(7,db.productDao().get(first.id).quantity,0);assertEquals(2,db.productDao().get(second.id).quantity,0);assertEquals("bottles",db.productDao().get(second.id).unit);assertEquals("MILK",db.productDao().get(first.id).sku);assertEquals("Whole",db.productDao().catalog("MILK").variation);}
 @Test public void permanentDeleteRequiresTrashAndRemovesChildren(){Product p=receive("MILK",1,4,false);try{repo.permanentlyDelete("MILK");fail();}catch(IllegalArgumentException expected){}repo.delete("MILK");repo.permanentlyDelete("MILK");assertNull(db.productDao().get(p.id));assertNull(db.productDao().catalog("MILK"));assertTrue(db.productDao().movements().isEmpty());}
 @Test public void measurementAndReceivedAmountsPersist(){Product p=new Product("Juice","","LOT","Beverages",8,null);p.stockReference="B1";p.barcode="34567890";p.variation="Original";p.brand="Test";p.packSize="150ml";p.measurementValue="150";p.measurementUnit="ml";p.received=10;repo.registerQuantities(p,false);assertEquals(10,db.productDao().get(p.id).received,0);assertEquals(8,db.productDao().get(p.id).quantity,0);assertEquals("ml",db.productDao().catalog(p.sku).measurementUnit);String original=p.sku;Product edit=p.copy();edit.measurementValue="200";edit.packSize="200ml";edit.received=12;edit.quantity=9;repo.editFull(edit,true);assertEquals(original,db.productDao().get(p.id).sku);assertEquals(12,db.productDao().get(p.id).received,0);assertEquals("200",db.productDao().get(p.id).measurementValue);edit.quantity=13;try{repo.editFull(edit,true);fail();}catch(IllegalArgumentException expected){}assertEquals(9,db.productDao().get(p.id).quantity,0);}
 @Test public void editableReferenceUniquePerProduct(){Product first=receive("MILK",1,4,false);Product second=receive("MILK",3,2,true);Product edit=second.copy();edit.stockReference=first.stockReference.toLowerCase(java.util.Locale.ROOT);try{repo.editFull(edit,true);fail();}catch(IllegalArgumentException expected){}edit.stockReference="DELIVERY-03";edit.measurementUnit="sachets";edit.measurementValue="1";edit.category="Custom groceries";repo.editFull(edit,true);assertEquals("DELIVERY-03",db.productDao().get(second.id).stockReference);assertTrue(db.productDao().options("unit").contains("sachets"));repo.delete("MILK");repo.permanentlyDelete("MILK");assertTrue(db.productDao().options("category").contains("Custom groceries"));}
 @Test public void categoriesNormalizeAcrossParentAndBatches(){Product p=receive("MILK",4,5,false);Product edit=p.copy();edit.category="  Pet   Food  ";repo.edit(edit);edit.category="pet food";repo.edit(edit);assertEquals("Pet Food",db.productDao().get(p.id).category);assertEquals("Pet Food",db.productDao().catalog("MILK").category);assertEquals(1,java.util.Collections.frequency(db.productDao().options("category"),"Pet Food"));assertFalse(db.productDao().options("category").contains("pet food"));}
 @Test public void fullUnitLabelsPreserveCanonicalStorage(){assertEquals("Gram (g)",SavedChoice.displayUnit("g"));assertEquals("Liter (L)",SavedChoice.displayUnit("l"));assertEquals("ml",SavedChoice.normalize("Milliliter (ml)"));assertEquals("425",Measurement.detect("425 g").value);}
 @Test public void lookupResponseUsesTagsAndStructuredQuantity() throws Exception {
  BarcodeLookup.Result r=BarcodeLookup.parse("{\"status\":1,\"product\":{\"product_name_en\":\"Example Drink\",\"categories_tags\":[\"en:beverages\"],\"product_quantity\":330,\"product_quantity_unit\":\"ml\"}}");
  assertEquals("Example Drink",r.name);assertEquals("Beverages",r.category);assertEquals("330",r.measurement.value);assertEquals("ml",r.measurement.unit);
 }
 @Test public void lookupCannotInferUnitsFromBrand() throws Exception {
  BarcodeLookup.Result r=BarcodeLookup.parse("{\"status\":1,\"product\":{\"product_name\":\"Century Tuna\"}}");assertEquals("Canned Goods",r.category);assertNull(r.measurement);
 }
 @Test public void measurementLookupUpdatesVisibleDropdownAndProtectsManualEdits(){
  androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{
   Context themed=new android.view.ContextThemeWrapper(ApplicationProvider.getApplicationContext(),R.style.Theme_ShelfLife);
   android.view.View form=android.view.LayoutInflater.from(themed).inflate(R.layout.dialog_product,null);
   MeasurementBinding binding=new MeasurementBinding(form,null);
   ((android.widget.EditText)form.findViewById(R.id.etName)).setText("Product 155g");
   binding.applyLookup(new Measurement("425","g"),"425g");
   assertEquals("425",binding.value());assertEquals("Gram (g)",((android.widget.EditText)form.findViewById(R.id.etMeasurementUnit)).getText().toString());
   ((android.widget.EditText)form.findViewById(R.id.etMeasurementValue)).setText("500");
   binding.applyLookup(new Measurement("155","g"),"155g");assertEquals("500",binding.value());
  });
 }
 @Test public void measurementDescriptionResponseAndStorage() throws Exception {
  BarcodeLookup.Result lookup=BarcodeLookup.parse("{\"status\":1,\"product\":{\"product_name\":\"Sardines\",\"generic_name\":\"Sardines in tomato sauce 425g\"}}");
  assertEquals("425",lookup.measurement.value);assertEquals("g",lookup.measurement.unit);
  Product product=receive("FISH",5,10,false);product.measurementValue=lookup.measurement.value;product.measurementUnit=lookup.measurement.unit;product.packSize="425g";repo.edit(product);
  assertEquals("425",db.productDao().get(product.id).measurementValue);assertEquals("g",db.productDao().catalog("FISH").measurementUnit);
 }
 @Test public void packagingResponseIncludesMeasurement() throws Exception {
  BarcodeLookup.Result lookup=BarcodeLookup.parse("{\"status\":1,\"product\":{\"product_name\":\"Drink\",\"packaging_text\":\"Net volume: 250ml\"}}");assertEquals("250",lookup.measurement.value);assertEquals("ml",lookup.measurement.unit);
 }
 @Test public void detectedMeasurementAllowsOthersAndManualCorrection(){
  androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{
   Context themed=new android.view.ContextThemeWrapper(ApplicationProvider.getApplicationContext(),R.style.Theme_ShelfLife);
   android.view.View form=android.view.LayoutInflater.from(themed).inflate(R.layout.dialog_product,null);
   MeasurementBinding binding=new MeasurementBinding(form,null);
   try{binding.applyLookup(BarcodeLookup.parse("{\"status\":1,\"product\":{\"quantity\":\"155g\"}}").measurement,"155g");}catch(Exception e){throw new AssertionError(e);}
   assertEquals("155",binding.value());assertEquals("g",binding.unit());
   android.widget.AutoCompleteTextView unit=form.findViewById(R.id.etMeasurementUnit);
   assertEquals("Gram (g)",unit.getText().toString());
   unit.setText("Others",false);
   assertEquals(android.view.View.VISIBLE,form.findViewById(R.id.etCustomMeasurementUnitBox).getVisibility());
   ((android.widget.EditText)form.findViewById(R.id.etCustomMeasurementUnit)).setText("sachets");
   ((android.widget.EditText)form.findViewById(R.id.etMeasurementValue)).setText("6");
   assertEquals("6",binding.value());assertEquals("sachets",binding.unit());
   binding.applyLookup(new Measurement("155","g"),"155g");
   assertEquals("6",binding.value());assertEquals("sachets",binding.unit());
   unit.setText("Milliliter (ml)",false);
   assertEquals(android.view.View.GONE,form.findViewById(R.id.etCustomMeasurementUnitBox).getVisibility());
   assertEquals("ml",binding.unit());
  });
 }
}
